use std::fs
use std::env
use std::process

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut count = 0
    let mut status = 0
    if files.len() == 0 {
        files.push("/dev/stdin")
    }
    for f in files {
        match fs::read_to_string(f) {
            Ok(text) => {
                if number {
                    for line in text.lines() {
                        count += 1
                        println("${count:>6}\t${line}")
                    }
                } else {
                    print(text)
                }
            }
            Err(_) => {
                println("cat: ${f}: No such file")
                status = 1
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}

